let permissions=null,membership=null;async function loadMembership(){const e=localStorage.getItem("cb_token");if(e)try{const n=await(await fetch("https://api.buildskil.com/api/membership/my-membership",{headers:{Authorization:`Bearer ${e}`}})).json();if(!n.success){alert(n.message);return}membership=n.membership,permissions=n.permissions,setupProtectedButtons()}catch(t){console.error(t)}}function hasPageAccess(e){return permissions?permissions.pages.includes("*")?!0:permissions.pages.includes(e):!1}function setupProtectedButtons(){permissions&&document.querySelectorAll(".protected-btn").forEach(e=>{const t=e.dataset.page;permissions.pages.includes("*")||permissions.pages.includes(t)||(e.innerHTML+=" \u{1F512}",e.addEventListener("click",function(o){o.preventDefault(),openModal()}))})}document.addEventListener("DOMContentLoaded",async()=>{await loadMembership()});function closeModal(){document.getElementById("upgradeModal").style.display="none"}function goToPricing(){window.location.href="price.html"}function checkChatbotAccess(){return userPlan==="free"?(openModal(),!1):!0}async function openProtectedPage(e){if(!permissions&&!await loadMembership())return;const t=e.split("/").pop();hasPageAccess(t)?window.location.href=e:alert("Upgrade your membership to access this feature.")}function openModal(){const e=document.getElementById("upgradeModal");e?e.style.display="flex":(alert("Upgrade your membership to access this feature."),window.location.href="../screen/price.html")}
